    resource_positions = observation.get('resources', [])
    territory_regions = observation.get('territory', [])
    mode = observation.get('mode', '')

    # Extract current position
    x, y = my_pos

    # Helper to find closest
    def closest(targets):
        min_dist = float('inf')
        target = None
        for t in targets:
            tx, ty = t
            dist = abs(tx - x) + abs(ty - y)
            if dist < min_dist:
                min_dist = dist
                target = t
        return target

    # Decide target
    target = None
    if resource_positions:
        target = closest(resource_positions)
    elif len(opponent_positions) >= 1:
        target = closest(opponent_positions)
    elif mode == 'territory_control' and territory_regions:
        target = closest(territory_regions)
    else:
        # No specific target, stay put as fallback
        return [0, 0]

