        return [0, 0]

    tx, ty = target
    dx = dy = 0
    if tx > x:
        dx = 1
    elif tx < x:
        dx = -1
    if ty > y:
        dy = 1
    elif ty < y:
        dy = -1

    return [dx, dy]

